if (segment_count - 1 > 0) {
    int delta_index = 0;
    int delta_sample_offset = 0;
    do {
        PathAttachmentSample* primary_delta_sample =
            (PathAttachmentSample*)((char*)primary_samples
                + delta_sample_offset);
        primary_delta_sample->delta_dir_to_next =
            (primary_delta_sample + 1)->transform.position -
            primary_delta_sample->transform.position;
        primary_delta_sample->delta_length =
            primary_delta_sample->delta_dir_to_next.Normalize();

        PathAttachmentSample* secondary_delta_sample =
            (PathAttachmentSample*)((char*)secondary_samples
                + delta_sample_offset);
        secondary_delta_sample->delta_dir_to_next =
            (secondary_delta_sample + 1)->transform.position -
            secondary_delta_sample->transform.position;
        secondary_delta_sample->delta_length =
            secondary_delta_sample->delta_dir_to_next.Normalize();

        ++delta_index;
        delta_sample_offset += (int)sizeof(PathAttachmentSample);
    } while (delta_index < segment_count - 1);
}

